//! Oracle rows for the port, generated by `target/canon/hhctrl.ocx/gen_rows.py`.
//!
//! Each expected value is the reply of Wine's verbatim `dlls/hhctrl.ocx` functions,
//! built with ASan and UBSan. [`oracle_rows_match_c`] checks the port against them.

use super::*;

/// (tag text, element name) from get_node_name.
const NODE_ROWS: &[(&[u8], &[u8])] = &[
    // <param name="x">
    (b"<param name=\x22x\x22>", b"param"),
    // <OBJECT	type="text/sitemap">
    (b"<OBJECT\x09type=\x22text/sitemap\x22>", b"OBJECT"),
    // </ul>
    (b"</ul>", b"/ul"),
];

/// (tag text, attribute name, value from get_attr) from get_attr.
type AttrRow<'a> = (&'a [u8], &'a [u8], Option<&'a [u8]>);
const ATTR_ROWS: &[AttrRow] = &[
    // <param name="Name" value="Index"> / name
    (
        b"<param name=\x22Name\x22 value=\x22Index\x22>",
        b"name",
        Some(b"Name"),
    ),
    // <param name="Name" value="Index"> / VALUE
    (
        b"<param name=\x22Name\x22 value=\x22Index\x22>",
        b"VALUE",
        Some(b"Index"),
    ),
    // <param name="x"> / value
    (b"<param name=\x22x\x22>", b"value", None),
    // <param name=x> / name
    (b"<param name=x>", b"name", None),
    // <param xname="a" name="b"> / name
    (
        b"<param xname=\x22a\x22 name=\x22b\x22>",
        b"name",
        Some(b"a"),
    ),
];

/// (URL, characters skipped) from skip_schema.
const SCHEMA_ROWS: &[(&[u8], usize)] = &[
    // its:Foo.htm
    (b"its:Foo.htm", 4),
    // MS-ITS:a/b.htm
    (b"MS-ITS:a/b.htm", 7),
    // mk:@msitstore:x
    (b"mk:@msitstore:x", 14),
    // http://x
    (b"http://x", 0),
];

/// (URL, is_chm result) from is_chm.
const CHM_ROWS: &[(&[u8], bool)] = &[
    // mk:@MSITStore:x.chm
    (b"mk:@MSITStore:x.chm", true),
    // mk:@msitstore:x.chm
    (b"mk:@msitstore:x.chm", false),
];

/// (fragment, decoded bytes before the code page step) from decode_html.
const DECODE_ROWS: &[(&[u8], &[u8])] = &[
    // Tom &amp; Jerry
    (b"Tom &amp; Jerry", b"Tom & Jerry"),
    // &copy; 2001
    (b"&copy; 2001", b"\xa9 2001"),
    // &lt;b&gt;
    (b"&lt;b&gt;", b"<b>"),
    // &#65;
    (b"&#65;", b"&#65;"),
    // a &unknown; b
    (b"a &unknown; b", b"a &unknown; b"),
    // &a&lt;
    (b"&a&lt;", b"&a<"),
    // &nbsp;x
    (b"&nbsp;x", b" x"),
    // &amp;amp;
    (b"&amp;amp;", b"&amp;"),
];

#[test]
fn oracle_rows_match_c() {
    for &(tag, name) in NODE_ROWS {
        assert_eq!(node_name(tag), name, "node {:?}", tag);
    }
    for &(tag, name, value) in ATTR_ROWS {
        assert_eq!(attr_value(tag, name), value, "attr {:?} {:?}", tag, name);
    }
    for &(url, skipped) in SCHEMA_ROWS {
        let wide: Vec<u16> = url.iter().map(|&c| u16::from(c)).collect();
        assert_eq!(
            wide.len() - strip_schema(&wide).len(),
            skipped,
            "schema {:?}",
            url
        );
    }
    for &(url, expected) in CHM_ROWS {
        let wide: Vec<u16> = url.iter().map(|&c| u16::from(c)).collect();
        assert_eq!(is_chm_url(&wide), expected, "chm {:?}", url);
    }
    for &(fragment, decoded) in DECODE_ROWS {
        assert_eq!(decode_entities(fragment), decoded, "decode {:?}", fragment);
    }
}
